bash -c python3 -c "
import json, re, signal, sys
sys.path.append('/workspace/work')
import tasks, tasks_mbpp
from eval_gen import extract_code, handler

for name, path, batch in [('Batch1', '/workspace/work/gen/0.json', tasks.DIAGNOSTIC_BATCH_1),
                          ('MBPP',   '/workspace/work/gen/2.json', tasks_mbpp.MBPP_DIAGNOSTIC)]:
    with open(path) as f:
        items = json.load(f)
    raw_pass = 0
    def_only_pass = 0
    rename_pass = 0
    by_start = {'fence': [0, 0], 'prose_short': [0, 0], 'prose_logic_hdr': [0, 0]}
    for idx, (item, task) in enumerate(zip(items, batch)):
        rep = item['reply']
        if rep.lstrip().startswith('\`\`\`'):
            cat = 'fence'
        elif '### ' in rep.split('\`\`\`')[0]:
            cat = 'prose_logic_hdr'
        else:
            cat = 'prose_short'
        by_start[cat][1] += 1

        code = extract_code(rep)
        # Strip top-level assert / print lines after def block to check if the function itself was actually right!
        lines = code.splitlines()
        clean_lines = []
        seen_def = False
        for ln in lines:
            if ln.startswith('def ') or ln.startswith('class '):
                seen_def = True
                clean_lines.append(ln)
            elif seen_def and (ln.startswith('assert ') or ln.startswith('print(') or ln.startswith('# Test') or ln.startswith('# Example')):
                break
            else:
                clean_lines.append(ln)
        clean_code = '\n'.join(clean_lines)

        for mode, c in [('raw', code), ('no_trailing_assert', clean_code), ('rename_too', clean_code)]:
            ns = {}
            signal.signal(signal.SIGALRM, handler)
            signal.alarm(2)
            ok = False
            try:
                exec(c, ns, ns)
                if mode == 'rename_too' and task['func'] not in ns:
                    callables = [v for k, v in ns.items() if callable(v) and not k.startswith('__') and k not in ('Counter','deque')]
                    if len(callables) == 1:
                        ns[task['func']] = callables[0]
                if task['func'] in ns:
                    for t in task['tests']:
                        exec(t, ns, ns)
                    ok = True
            except Exception:
                ok = False
            finally:
                signal.alarm(0)
            if ok:
                if mode == 'raw':
                    raw_pass += 1
                    by_start[cat][0] += 1
                elif mode == 'no_trailing_assert':
                    def_only_pass += 1
                    if raw_pass < def_only_pass:
                        pass
                elif mode == 'rename_too':
                    rename_pass += 1
        # Print if rescued!
        ns1, ns2 = {}, {}
        try:
            exec(clean_code, ns2, ns2)
            if task['func'] not in ns2:
                callables = [v for k, v in ns2.items() if callable(v) and not k.startswith('__') and k not in ('Counter','deque')]
                if len(callables) == 1: ns2[task['func']] = callables[0]
            for t in task['tests']: exec(t, ns2, ns2)
            ok2 = True
        except Exception:
            ok2 = False
        try:
            exec(code, ns1, ns1)
            for t in task['tests']: exec(t, ns1, ns1)
            ok1 = True
        except Exception:
            ok1 = False
        if ok2 and not ok1:
            print(f'  RESCUED in {name} #{idx} ({task[\"func\"]}): failed raw, PASSED when trailing asserts stripped / func renamed!')

    print(f'{name}: raw={raw_pass}/32, no_trailing_assert={def_only_pass}/32, +rename={rename_pass}/32 | by_start={by_start}')
"

